from parsing import parse_flags

def test_flag_boolean_type():
    assert parse_flags(["--verbose"]) == {"verbose": True}

def test_flag_ignores_positional():
    assert parse_flags(["file.txt", "--x"]) == {"x": True}

def test_flag_mixed():
    assert parse_flags(["--a", "--b=2"]) == {"a": True, "b": "2"}
